def test_native_observed_source_commit_precedes_projection_and_exact_repeat_is_idempotent(tmp_path, _fpbca_d2_capture):
    _fpbca_d2_capture.begin_flow()
    try:
        fact, db, memory = _setup(tmp_path)
        ref = _commit(fact)
        assert db.memory == {}
        first = memory.project_artifact(ref)
        before = dict(db.memory)
        assert memory.project_artifact(ref) == first
        assert db.memory == before and len(before) == 1
        record = memory.runtime.resolve_record(first[0])
        assert record.source_binding.primary_source.exact_source_ref == ref.model_dump(mode='json')
        assert set(record.projection.projection_payload) == {'source_ref'}
    finally:
        _fpbca_d2_capture.safe_emit(row='D2/REC-D', selector='backend/tests/test_fpbca_final65_rec_d_step7_durable_memory_persistence.py::test_native_observed_source_commit_precedes_projection_and_exact_repeat_is_idempotent', local_values=locals(), original_point={'path': 'D:\\MyCode\\rag-agent-shared\\backend\\tests\\test_step7_durable_memory_persistence.py', 'sha256': '7507f2af7b3f3e980695ae78895a9e9bf1409e14984c6588767679b3ee52b88f', 'function': 'test_source_commit_precedes_projection_and_exact_repeat_is_idempotent', 'line': 53, 'native_operation': 'EXACT_UNCHANGED_ORIGINAL_NATIVE_CONTROL_FLOW', 'native_refs': []}, flow={'scope': 'ACTUAL_REGISTERED_FACT_SOURCE_AND_DURABLE_MEMORY_OWNER_WITH_EXPLICIT_CONTROLLED_DB_API; NOT_LIVE_POSTGRES', 'controlled_boundary': 'EXACT_EXISTING_SOURCE_MEMORY_CHECKPOINT_CONTROLLED_LOCAL_BOUNDARY', 'cold_reopen': True, 'exact_replay': True, 'replay_symbols': ['TargetDurableMemoryComposition.project_artifact', 'PostgresDurableMemoryStore.put_memory_record_if_absent_or_same'], 'concurrent': False, 'native_local_names': ['ref', 'source', 'refs', 'first', 'record', 'before'], 'dispatch_scope': 'ACTUAL_CONTROLLED_DB_API_CONNECTION_COMMIT_ENTRIES_ONLY; SERVER_PHYSICAL_IO_AND_LIVE_POSTGRES_UNMEASURED', 'field_dispositions': {'actual_settlement_count': {'status': 'SOURCE_BOUND_N_A', 'reason': 'CONTROLLED_DURABLE_MEMORY_DB_API_OWNER_FLOW_HAS_NO_MODEL_PROVIDER_TOKEN_ACCOUNT', 'evidence_scope': 'EXACT_REGISTERED_MEMORY_PROJECTION_ONLY; DB_COMMITS_ARE_NOT_PROVIDER_SETTLEMENTS', 'source_decision': {'path': 'D:\\MyCode\\rag-agent-shared\\docs\\fpbca_bcd_closure_design_v0_2_20261007\\03_D_VERIFICATION_DESIGN_V0_2.md', 'sha256': '86c300eb36233b96858168d33aa2d69167de1c93c18a115b1fc4dc387b9aa085', 'authority': 'D5_PHYSICAL_MUTATION_ACCOUNTING_WHERE_RELEVANT', 'section': 'D5 required native fields WHERE RELEVANT'}}}, 'cold_symbols': ['TargetDurableMemoryComposition.__init__']})

